query CharizardTypes($name: String!, $limit: Int!, $typeLimit: Int!) {
  pokemon(where: {name: {_eq: $name}}, limit: $limit) {
    id
    name
    pokemontypes(limit: $typeLimit, order_by: {slot: asc}) {
      slot
      type {
        id
        name
      }
    }
  }
}

