}

query JohtoSteel($generationId: Int!, $typeName: String!, $isDefault: Boolean!, $limit: Int!) {
  pokemonspecies(where: {
    generation_id: {_eq: $generationId}
    pokemons: {
      is_default: {_eq: $isDefault}
      pokemontypes: {type: {name: {_eq: $typeName}}}
    }
  }, order_by: {id: asc}, limit: $limit) {
    id
    name
  }
}

query ResolveAnswerEntities($names: [String!]!, $limit: Int!) {
  ability(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) { id name }
  item(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) { id name }
  move(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) { id name }
  pokemon(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) { id name }
}

