queries.query:
query Gen1LevitatePokemon($genId: Int!, $abilityName: String!, $limit: Int!) {
  pokemon(
    where: {
      pokemonspecy: {generation_id: {_eq: $genId}}
      pokemonabilities: {ability: {name: {_eq: $abilityName}}}
    }
    order_by: {id: asc}
    limit: $limit
  ) {
    id
    name
    is_default
    pokemonspecy {
      id
      name
      generation_id
    }
    pokemonabilities(where: {ability: {name: {_eq: $abilityName}}}, limit: 5) {
      is_hidden
      slot
      ability {
        id
        name
      }
    }
  }
}

query FirstGenLevitate($generationId: Int!, $isDefault: Boolean!, $abilityName: String!, $limit: Int!) {
  pokemonspecies(
    where: {
      generation_id: {_eq: $generationId}
      pokemons: {
        is_default: {_eq: $isDefault}
        pokemonabilities: {ability: {name: {_eq: $abilityName}}}
      }
    }
    order_by: {id: asc}
    limit: $limit
  ) {
    id
    name
    pokemons(limit: 1, where: {is_default: {_eq: $isDefault}}) {
      id
      name
      pokemonabilities(limit: 10, order_by: {slot: asc}) {
        ability { id name }
        is_hidden
        slot
      }
    }
  }
}

query GetWonderGuard($name: String!, $language: String!, $limit: Int!, $textLimit: Int!) {
  ability(where: {name: {_eq: $name}}, limit: $limit) {
    id
    name
    abilityeffecttexts(limit: $textLimit, where: {language: {iso639: {_eq: $language}}}) {
      effect
